```sql
-- 1. Crear tabla
CREATE TABLE productos (
  id INT PRIMARY KEY AUTO_INCREMENT,
  nombre VARCHAR(100) NOT NULL,
  precio DECIMAL(10,2) NOT NULL
);

-- 2. Añadir stock
ALTER TABLE productos ADD COLUMN stock INT DEFAULT 0;

-- 3. Añadir categoria
ALTER TABLE productos ADD COLUMN categoria VARCHAR(50);

-- 4. CHECK en precio
ALTER TABLE productos ADD CONSTRAINT chk_precio CHECK (precio > 0);

-- 5. categoria NOT NULL
ALTER TABLE productos MODIFY COLUMN categoria VARCHAR(50) NOT NULL;

-- 6. UNIQUE en nombre
ALTER TABLE productos ADD CONSTRAINT uq_nombre UNIQUE (nombre);

-- 7. Eliminar stock
ALTER TABLE productos DROP COLUMN stock;

-- Verificar estructura
DESCRIBE productos;
```
